from django.db import models
from django.db.models.fields import uuid

# Create your models here.
class Robot(models.Model):
    #UUIDField is a 128-bit universally unique identifier (UUID) that is generated by the system.
    #UUID is more secure than an auto-incrementing integer because it is not predictable and can be used to identify a unique object.
    #default=uuid.uuid4 is a function that generates a random UUID.
    #editable=False means that the field is not editable.
    id=models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False)
    name=models.CharField(max_length=100)
    serial_number=models.CharField(max_length=100,unique=True)
    battery_level=models.PositiveSmallIntegerField(default=100)
    max_speed=models.FloatField(default=10.0)
    is_active=models.BooleanField(default=True)
    status=models.CharField(max_length=100)
    created_at=models.DateTimeField(auto_now_add=True)
    updated_at=models.DateTimeField(auto_now=True)
    #class Meta is used to define the metadata for the model.
    #if we want, for example, to customize the table name, we can use the db_table attribute.
    class Meta:
        #db_table is used to define the table name on the database.
        db_table='robots'
        #ordering is used to define the default ordering for the model.
        #The robot tuples are sorted by max_speed in descending order 
        # and then by status in ascending order.
        ordering=['-max_speed','status']
        #indexes is used to define the indexes like indexes on SQL
        #indexes are used to improve the performance of the database.
        indexes=[
            models.Index(fields=['name']),
            models.Index(fields=['serial_number']),
        ]
        constraints=[
            models.UniqueConstraint(fields=['name','serial_number'],
            name='unique_robot',),        
            ]

    